function [ dx ] = modelo_eq( t_out, x, ws, ks,ts,reg,ns,ne,te,n_s,n_c,ns_a,ts_frozen,points,tal,est,yi,utarg,tstarg,nstarg)
[u] = ver_reg_est1(ws,yi,t_out);
[uref] = ver_reg_est1(ws,yi,t_out);
Ad = 2.1428*10^17   ;
Ed = 14897          ;
Ap = 3.816*10^10    ;
Ep = 3557           ;
At = 4.50*10^12     ;
Et = 843            ;
fi = 0.6            ;
DeltaHr = -6.99*10^4;
hA = 1.05*10^6      ;
rhoCp = 1506        ;
rhocCpc = 4043      ;
Mm = 104.14         ;
Qim = 108           ;
Qi = 108            ;
Qmm = 378           ;
Qc =1               ;
V = 3000            ;
Vc = 3312.4         ;
If = 0.5888         ;
Mf = 8.6981         ;
Tf = 330            ;
Tcf = 295           ;

y(1)=(Ad*exp(-Ed/x(3))                     );
y(2)=(Ap*exp(-Ep/x(3))                     );
y(3)=(At*exp(-Et/x(3))                     );
y(4)=((Qmm/Qim)*Qi                         );
y(5)=(1.5*y(4) - Qi                        );
y(6)=(Qi + y(5) + y(4)                     );
y(7)=(( ( ( 2*fi*y(1)*x(1) )/y(3) )^(0.5) ));

dx(1)=(((Qi*If - y(6)*x(1)) / V) - y(1)*x(1)                                             )*tal;
dx(2)=(( y(4)*Mf - y(6)*x(2) )/ V - y(2)*x(2)*y(7)                                       )*tal;
dx(3)=(y(6)*(Tf - x(3))/V + (-DeltaHr/rhoCp)*y(2)*x(2)*y(7) -(hA/(rhoCp*V))*(x(3) - x(4)))*tal;
dx(4)=(u(1)*(Tcf - x(4))/Vc + (hA/(rhocCpc*Vc))*(x(3) - x(4))                            )*tal;
dx(5)=(0.5*y(3)*y(7)^2 - (y(6)*x(5))/V                                                   )*tal;
dx(6)=(Mm*y(2)*x(2)*y(7) - (y(6)*x(6))/V                                                 )*tal;
dx(7)=(5*Mm*y(2)*x(2)*y(7) + 3*Mm*((y(2)^2)/y(3))*(x(2)^2) - (y(6)/V)*x(7)               )*tal;
dx(8)=(x(6)*2.5*Qmm*Qi/Qim                                                               )*tal;
dx(9)=(u(1)-320                                                               )*tal;
dx=transp(dx);
end                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
